#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_head; /* next write position */
    size_t tail; /* next read position */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(ringbuf_t));
    if (!rb)
        return NULL;

    rb->buf = malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;

    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static size_t count(const ringbuf_t *rb)
{
    if (rb->head >= rb->tail)
        return rb->head - rb->tail;
    return rb->capacity - (rb->tail - rb->head);
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return count(rb);
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t n;
    size_t avail;

    if (!rb || !data || len == 0)
        return 0;

    avail = rb->capacity - count(rb);
    if (len > avail)
        len = avail;

    /* First chunk: from head to end of buffer */
    n = rb->capacity - rb->head;
    if (len > n)
        n = len;

    memcpy(rb->buf + rb->head, data, n);
    rb->head += n;
    if (rb->head == rb->capacity)
        rb->head = 0;

    /* Second chunk: wraps around */
    if (len > n) {
        memcpy(rb->buf, data + n, len - n);
        rb->head += (len - n);
    }

    return len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;
    size_t sz;

    if (!rb || !out || len == 0)
        return 0;

    sz = count(rb);
    if (len > sz)
        len = sz;

    /* First chunk: from tail to end of buffer */
    n = rb->capacity - rb->tail;
    if (len > n)
        n = len;

    memcpy(out, rb->buf + rb->tail, n);
    rb->tail += n;
    if (rb->tail == rb->capacity)
        rb->tail = 0;

    /* Second chunk: wraps around */
    if (len > n) {
        memcpy(out + n, rb->buf, len - n);
        rb->tail += (len - n);
    }

    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;
    size_t sz;
    size_t tmp_head;

    if (!rb || !out || len == 0)
        return 0;

    sz = count(rb);
    if (len > sz)
        len = sz;

    /* Copy from a virtual head starting at rb->head */
    tmp_head = rb->head;

    n = rb->capacity - tmp_head;
    if (len > n)
        n = len;

    memcpy(out, rb->buf + tmp_head, n);
    tmp_head += n;
    if (tmp_head == rb->capacity)
        tmp_head = 0;

    if (len > n) {
        memcpy(out + n, rb->buf, len - n);
        tmp_head += (len - n);
    }

    return len;
}

