#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

int main(void) {
    /* Test create/destroy */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);

    /* Write some data */
    uint8_t wdata[] = {1,2,3,4,5};
    size_t n = rb_write(rb, wdata, 5);
    assert(n == 5);
    assert(rb_size(rb) == 5);

    /* Peek should show same data without removing */
    uint8_t peeked[5];
    n = rb_peek(rb, peeked, 5);
    assert(n == 5);
    assert(memcmp(peeked, wdata, 5) == 0);
    assert(rb_size(rb) == 5); /* unchanged */

    /* Read back */
    uint8_t rdata[5];
    n = rb_read(rb, rdata, 5);
    assert(n == 5);
    assert(memcmp(rdata, wdata, 5) == 0);
    assert(rb_size(rb) == 0);

    /* Wrap-around test: fill to edge and continue writing */
    uint8_t buf2[8];
    rb_write(rb, buf2, 8); /* fills buffer */
    assert(rb_size(rb) == 8);

    /* Write more — should store what fits (0 free, returns 0) */
    n = rb_write(rb, wdata, 5);
    assert(n == 0);

    /* Read some, then write again */
    uint8_t tmp[4];
    rb_read(rb, tmp, 4);
    assert(rb_size(rb) == 4);
    n = rb_write(rb, wdata, 5);
    assert(n == 4); /* only 4 bytes fit */

    /* Read everything and verify order */
    uint8_t out[8];
    rb_read(rb, tmp, 4); /* drain remaining original data */
    n = rb_read(rb, out, 4);
    assert(n == 4);
    for (size_t i = 0; i < 4; i++)
        assert(out[i] == wdata[i]);

    /* Clear test */
    rb_clear(rb);
    assert(rb_size(rb) == 0);

    /* NULL safety */
    rb_destroy(NULL);
    assert(rb_write(NULL, wdata, 5) == 0);
    assert(rb_read(NULL, rdata, 5) == 0);
    assert(rb_peek(NULL, peeked, 5) == 0);
    assert(rb_size(NULL) == 0);
    assert(rb_capacity(NULL) == 0);
    rb_clear(NULL);

    /* Invalid capacity */
    assert(rb_create(0) == NULL);

    rb_destroy(rb);

    printf("All tests passed.\n");
    return 0;
}
EOF

